WITH session_totals AS (SELECT session_id, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, SUM(CASE WHEN page = '/product' THEN 1 ELSE 0 END) AS product_count FROM web_events GROUP BY session_id) SELECT s.id, s.country, s.device, st.avg_duration_sec, st.product_count FROM sessions s INNER JOIN session_totals st ON s.id = st.session_id WHERE st.product_count >= 42 ORDER BY st.product_count DESC
